  "explain": "📖 교재 근거 (교재: L2816):\n> 해설: 맞춤형화장품판매업자는 혼합·소분 전에 내용물 및 원료의 사용기한 또는 개봉 후 사용기간을 확인해야 하며, 사용기한이 지난 것은 사용하지 않아야 한다. 또한 혼합·소분에 사용되는 내용물의 사용기한을 초과하여 맞춤형화장품의 사용기한을 정하지 않아야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
