  "explain": "📖 교재 근거 (교재: L2434):\n> 해설: 사용 제한 원료는 별표 2(사용상 제한 필요 원료)와 기능성화장품 고시 원료이다. 단, 화장품책임판매업자가 해당 원료를 포함하여 기능성화장품에 대한 심사를 받은 경우는 제외된다. 별표 1은 배합 금지 원료이다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
