  "derivedFrom": "subject4_q36",
  "explain": "📖 법령 근거 (교재: L1612):\n> 해설: 저울 점검은 영점(매일 가동 전), 수평(매일 가동 전), 정기 점검(1개월 1회, 표준 분동)으로 구분된다. 직선성 ±0.5%, 정밀성 ±0.5%, 편심오차 ±0.1% 이내가 기준이다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
