  "explain": "📖 교재 근거 (교재: L1396):\n> 참고 - 세포막복합체(CMC, Cell Membrane Complex): 모표피와 모피질 안의 내용물들이 빠져나가지 않게 잡아주는 역할을 하며, 부족 시 모발 손상의 주요 원인이 됨\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
