  "citation": "📖 교재: L1158 (출처: 과목4 문제은행 Q39)",
  "stem": "다음 중 각질 세포가 기저층에서 분열하여 각질층으로 이동하고, 최종적으로 피부 표면에서 비듬이나 때의 형태로 탈락하기까지 소요되는 일반적인 각화 주기(Turnover Cycle)의 기간에 해당하는 것을 모두 고른 것은?",
