  "citation": "📖 교재: L593 (출처: 과목4 문제은행 Q40)",
  "stem": "다음 중 맞춤형화장품 조제관리사가 혼합 제품의 pH(수소이온농도)를 측정하여 품질 기준 적합 여부를 판정할 때 준수해야 하는 오차 범위에 해당하는 것을 모두 고른 것은?",
