  "explain": "📖 교재 근거 (교재: L666):\n화장품의 취급·사용 시 인지되는 안전성 관련 정보를 체계적·효율적으로 수집·검토·평가하여 적절한 안전대책을 강구함으로써 국민 보건상 위해를 방지하기 위해 「화장품 안전성 정보관리 규정」을 고시해 두고 있다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
