  "explain": "📖 교재 근거 (교재: L1192):\n| 기저층<br>(Basal Layer) | • 단층의 원추형 유핵세포층<br>• 진피의 모세혈관으로부터 영양분과 산소를 공급받아 세포분열 촉진<br>• 각질형성세포(케라티노사이트), 멜라닌형성세포(멜라노사이트), 머켈세포 존재<br>• 각질형성세포와 멜라닌형성세포는 4:1~10:1 비율로 존재함 |",
