  "explain": "📖 교재 근거 (교재: L1226):\n| 기저층 (각질형성세포) | 각질형성세포(케라티노사이트, Keratinocyte) | • 각질층을 구성하는 각질세포를 만드는 세포<br>• 각화주기: 기저층에서 세포가 만들어지고 각질층까지 이동하여 서서히 떨어지는 과정으로 28일 정도 주기로 교체됨 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
