  "derivedFrom": "subject4_q64",
  "explain": "📖 법령 근거 (교재: L601):\n| 제12조의2<br>맞춤형화장품 판매업자의 준수사항 🎯 기출 | • 맞춤형화장품 판매장 시설·기구를 정기적으로 점검하여 보건위생상 위해가 없도록 관리할 것<br>• 다음의 혼합·소분 안전관리기준을 준수할 것<br>&nbsp;&nbsp;- 혼합·소분 전에 혼합·소분에 사용되는 내용물 또는 원료에 대한 품질성적서를 확인할 것<br>&nbsp;&nbsp;- 혼합·소분 전에 손을 소독하거나 세정할 것(다만, 혼합·소분 시 일회용 장갑을 착용하는 경우에는 그렇지 않음)<br>&nbsp;&nbsp;- 혼합·소분 전에 혼합·소분된 제품을 담을 포장용기의 오염 여부를 확인할 것<br>&nbsp;&nbsp;- 혼합·소분에 사용되는 장비 또는 기구 등은 사용 전에 그 위생 상태를 점검하고, 사용 후에는 오염이 없도록...\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
