  "explain": "📖 교재 근거 (L1377):\n| 에피큐티클(Epicuticle) | • 가장 바깥쪽의 두께 100Å 정도의 얇은 막<br>• 아미노산 중 시스틴의 함유량이 많음<br>• 각질 용해성 또는 단백질 용해성의 약품(친유성, 알칼리 용액)에 대한 저항성이 가장 강한 층<br>• 수증기는 통하지만 물은 통과하지 못하는 구조로 딱딱하고 부서지기 쉽기 때문에 물리적인 자극에 약함 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
