  "explain": "📖 교재 근거 (교재: L587):\n| 제3조의3<br>맞춤형화장품판매업 결격사유 🎯 기출 | • 피성년후견인 또는 파산 선고를 받고 복권되지 않은 자<br>• 「화장품법」 또는 「보건범죄 단속에 관한 특별조치법」을 위반하여 금고 이상의 형을 선고받고 집행이 끝나거나(집행이 끝난 것으로 보는 경우를 포함) 집행이 면제되지 아니한 자, 또는 금고 이상의 형의 집행유예를 선고받고 그 유예기간 중에 있는 자<br>• 등록 취소 또는 영업소가 폐쇄된 날부터 1년이 지나지 않은 자 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
  "source": "맞춤형화장품의 이해 (400제)",
  "answer": "3"
