  "explain": "📖 교재 근거 (교재: L603):\n| 제8조의4<br>맞춤형화장품 판매업의 시설기준 | 맞춤형화장품판매업을 신고하려는 자는 맞춤형화장품의 혼합·소분 공간을 그 외의 용도로 사용되는 공간과 분리 또는 구획하여 갖추어야 함. 다만, 혼합·소분 과정에서 맞춤형화장품의 품질·안전 등 보건위생상 위해가 발생할 우려가 없다고 인정되는 경우에는 혼합·소분 공간을 분리 또는 구획하여 갖추지 않아도 됨 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
