  "explain": "📖 교재 근거 (교재: L2959):\n> 해설: 화장품제조업자, 화장품책임판매업자 또는 맞춤형화장품판매업자는 자료 제출 요청일로부터 15일 이내에 실증 자료를 제출해야 한다. 실증 방법은 학술적으로 널리 알려져 있거나 관련 산업 분야에서 일반적으로 인정되는 과학적·객관적 방법이어야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
