  "explain": "📖 교재 근거 (교재: L1275):\n| 피지선 | • 얼굴, 두피, 가슴에 많으며, 손바닥, 발바닥을 제외한 전신에 분포되어 있음<br>• 남성호르몬(테스토스테론)이 피지선을 자극하면 피지가 분비됨<br>• 지용성 분비물을 생성<br>• 피부와 모발에 윤기 부여, 피부 보호<br>• 과잉 분비 시 여드름 발생의 원인이 됨 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
