  "explain": "📖 교재 근거 (교재: L1505):\n| 색소침착 피부 | • 멜라닌이 비정상적으로 과잉 생성되면서 과색소침착이 일어난 피부<br>• 자외선, 스트레스, 여성호르몬, 내장장애 등의 원인으로 발생<br>• 자외선의 종류<br>&nbsp;&nbsp;- UVA: 320~400nm 장파장으로 광노화의 원인 🎯 기출<br>&nbsp;&nbsp;- UVB: 290~320nm 중파장으로 일광화상, 홍반의 원인<br>&nbsp;&nbsp;- UVC: 200~290nm 단파장으로 피부암의 원인, 살균·소독작용 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
