  "explain": "📖 교재 근거 (교재: L1177):\n> 해설: 피부의 체온조절 기능은 모세혈관의 확장(열 확산→체온 하강)과 수축(열 차단→체온 상승)을 통해 이루어진다. 비타민 D 합성은 자외선과 콜레스테롤이 관여하며, 호흡은 전체의 0.6~1.0%를 차지한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
