  "derivedFrom": "subject4_q250",
  "explain": "📖 법령 근거 (교재: L608):\n| 제15조<br>폐업 등의 신고 🎯 기출 | • 영업자가 폐업 또는 휴업하거나 휴업 후 그 업을 재개하려는 경우에는 폐업, 휴업 또는 재개 신고서(전자문서로 된 신고서를 포함함)에 화장품제조업 등록필증, 화장품책임판매업 등록필증 또는 맞춤형화장품판매업 신고필증(폐업·휴업만 해당함)을 첨부하여 지방식품의약품안전청장에게 제출해야 함<br>• 「화장품법」에 따른 폐업 또는 휴업 신고를 하려는 자는 「부가가치세법 시행규칙」 별지 제9호 폐업·휴업신고서를 지방식품의약품안전청장에게 송부해야 함<br>• 「부가가치세법」에 따른 폐업 또는 휴업신고를 같이 하려는 자는 관할 세무서장에게 「부가가치세법 시행규칙」 별지 제11호와 「화장품법」에 따른 폐업·휴업신고서를 함께 제출해야 하는데, 영업자가 이 신고서들을 지방식품의약품안전청장과 관할 세무서장 중 한 곳에 제출할 경우, 지방식품의약품안전청장과 관할 세무서장은 즉시 서로에게 송부해야 함 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
